  const accentBar = new THREE.Mesh(accentBarGeo, accentBarMat);
  accentBar.position.set(-rowWidth / 2 + 0.022, 0, 0.002);
  group.add(accentBar);

  // Paper-tinted text area indicator (subtle)
  const textAreaOpacity = uniform(0);
  const textAreaGeo = new THREE.PlaneGeometry(rowWidth * 0.55, rowHeight * 0.35);
  const textAreaMat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  textAreaMat.colorNode = color(COLORS.paper);
  textAreaMat.opacityNode = textAreaOpacity;
  const textArea = new THREE.Mesh(textAreaGeo, textAreaMat);
  textArea.position.set(-rowWidth * 0.18, 0.04, 0.0005);
  group.add(textArea);

  // Meta text area indicator (right side, smaller)
  const metaAreaOpacity = uniform(0);
  const metaAreaGeo = new THREE.PlaneGeometry(rowWidth * 0.15, rowHeight * 0.22);
  const metaAreaMat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  metaAreaMat.colorNode = color(COLORS.paper);
  metaAreaMat.opacityNode = metaAreaOpacity;
  const metaArea = new THREE.Mesh(metaAreaGeo, metaAreaMat);
  metaArea.position.set(rowWidth * 0.32, 0.04, 0.0005);
  group.add(metaArea);

  // State
  const state = {
    isHovered: false,
    isFocused: false,
    isPressed: false
  };

  const timelines = [];
  let activeTl = null;

  // Kill active timeline helper
  function killActive() {
    if (activeTl) {
      activeTl.kill();
      activeTl = null;
    }
  }

  // Entrance animation
  const entranceTl = gsap.timeline();
  entranceTl.to(opacityUniform, { value: 1, duration: 0.5, ease: 'power2.out' }, 0);
  entranceTl.to(textAreaOpacity, { value: 0.06, duration: 0.6, ease: 'power2.out' }, 0.1);
  entranceTl.to(metaAreaOpacity, { value: 0.04, duration: 0.6, ease: 'power2.out' }, 0.15);
  entranceTl.to(group.position, { 
    y: pos[1], 
    duration: 0.7, 
    ease: 'power3.out' 
  }, 0);
  timelines.push(entranceTl);

  // Hover in
  function onHoverIn() {
    if (state.isPressed) return;
    state.isHovered = true;

    const tl = gsap.timeline();
    tl.to(group.position, {
      y: pos[1] + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    }, 0);
    tl.to(dividerOpacity, {
      value: 0.65,
      duration: 0.4,
      ease: 'power2.out'
    }, 0);
    tl.to(textAreaOpacity, {
      value: 0.1,
      duration: 0.4,
      ease: 'power2.out'
    }, 0);
    tl.to(metaAreaOpacity, {
      value: 0.07,
      duration: 0.4,
      ease: 'power2.out'
    }, 0);
    timelines.push(tl);
  }

  // Hover out
  function onHoverOut() {
    state.isHovered = false;

    const tl = gsap.timeline();
    tl.to(group.position, {
      y: pos[1],
      duration: 0.5,
      ease: 'power3.out'
    }, 0);
    tl.to(dividerOpacity, {
      value: state.isFocused ? 0.75 : 0,
      duration: 0.4,
      ease: 'power2.out'
    }, 0);
    tl.to(textAreaOpacity, {
      value: 0.06,
      duration: 0.4,
      ease: 'power2.out'
    }, 0);
    tl.to(metaAreaOpacity, {
      value: 0.04,
      duration: 0.4,
      ease: 'power2.out'
    }, 0);
    timelines.push(tl);
  }

  // Press down
  function onPressDown() {
    state.isPressed = true;

    const tl = gsap.timeline();
    tl.to(group.scale, {
      x: scl[0] * 0.97,
      y: scl[1] * 0.97,
      z: scl[2] * 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)'
    }, 0);
    tl.to(dividerOpacity, {
      value: 0.9,
      duration: 0.12,
      ease: 'power2.out'
    }, 0);
    timelines.push(tl);
  }

  // Press up
  function onPressUp() {
    state.isPressed = false;

    const tl = gsap.timeline();
    tl.to(group.scale, {
      x: scl[0],
      y: scl[1],
      z: scl[2],
      duration: 0.3,
      ease: 'power4.out'
    }, 0);
    tl.to(dividerOpacity, {
      value: state.isHovered ? 0.65 : (state.isFocused ? 0.75 : 0),
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
    timelines.push(tl);
  }

  // Focus in
  function onFocusIn() {
    state.isFocused = true;

    const tl = gsap.timeline();
    tl.to(accentOpacity, {
      value: 0.9,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
    tl.to(dividerOpacity, {
      value: 0.75,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
    timelines.push(tl);
  }
